update t_sku_stock
set available_stock = available_stock - #{quantity},
    locked_stock = locked_stock + #{quantity},
    version = version + 1
where sku_id = #{skuId}
  and available_stock >= #{quantity}

update t_sku_stock
set locked_stock = locked_stock - #{quantity},
    version = version + 1
where sku_id = #{skuId}
  and locked_stock >= #{quantity}

update t_sku_stock
set available_stock = available_stock + #{quantity},
    locked_stock = locked_stock - #{quantity},
    version = version + 1
where sku_id = #{skuId}
  and locked_stock >= #{quantity}

update t_sku_stock
set available_stock = #{availableStock},
    version = version + 1
where sku_id = #{skuId}
  and version = #{version}
  and #{availableStock} >= 0
